import{_ as t,c as o,o as a,ah as i}from"./chunks/framework.PvdZnrZd.js";const u=JSON.parse('{"title":"Add products via CSV","description":"Add products via CSV","frontmatter":{"title":"Add products via CSV","description":"Add products via CSV","author":"Chirag Tyagi"},"headers":[],"relativePath":"zenith/products/add-products-via-CSV.md","filePath":"zenith/products/add-products-via-CSV.md"}'),s={name:"zenith/products/add-products-via-CSV.md"};function n(r,e,l,d,p,c){return a(),o("div",null,[...e[0]||(e[0]=[i(`<p><a href="https://store.webkul.com/Shopify-Multi-Vendor-Marketplace.html" target="_blank" rel="noreferrer">Multi-vendor Marketplace app for Shopify</a> provides an ultimate solution for the e-Commerce merchants to convert their stores into fully-fledged marketplaces.</p><p>Despite the fact that Shopify is one of the simplest platforms to start an online business.</p><p>You have to deal with bulk product upload, add multiple sellers at a time, <strong>sellers requesting for the option to add products in bulk</strong> if you <a href="/zenith/introduction/">run an online marketplace</a>.</p><p>So, to have a simplified process, this guide will help you to understand how to upload the CSV files in the app and avoid errors.</p><blockquote><p>**The Multi-vendor Marketplace app facilitates:-<br> **Admin to add products in bulk via CSV.<br> Seller to add products via CSV.<br> Admin adding sellers via CSV.</p></blockquote><p><a href="https://youtu.be/kzct74e3dL4" target="_blank" rel="noreferrer">https://youtu.be/kzct74e3dL4</a></p><p>In the app, admin can allow sellers to add products in bulk via CSV. For this, the admin needs to follow the below-given steps:-</p><p>Go to the <strong>Product Configuration</strong> menu &gt;&gt;Enable <strong>Add Product by CSV</strong> tab.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/zsdwzwdwed.webp" alt="Product Configuration"></p><p>Admin Panel: Product Configuration</p><p>As soon as the admin configures the details, the option to add products via CSV gets reflected at the respective seller panels.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/zwrfwergzergz.webp" alt="Add product by CSV"></p><p>Seller Panel: Products</p><p>Now, the seller will click the <strong>Add Product by CSV</strong> button &amp; choose the methods using which he/she wants to upload products in bulk.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/csvaddmethod.webp" alt="add product in bulk"></p><p>The seller will get the instruction file in the app.</p><p><strong>Please Note:-</strong><br> If the export data is more than 500 lines, then you will receive export data in mail notifications in multiple files, each file with 5000 lines.</p><h3 id="seller-currency-compatibility-with-add-product-by-csv" tabindex="-1">Seller Currency compatibility with Add Product by CSV. <a class="header-anchor" href="#seller-currency-compatibility-with-add-product-by-csv" aria-label="Permalink to &quot;Seller Currency compatibility with Add Product by CSV.&quot;">​</a></h3><p>While adding the product through CSV, we have included a new column for seller currency.</p><p>When you enable the seller currency configuration in the Multivendor Marketplace Admin panel, the seller currency and compare price columns will be added to the CSV.</p><h2 id="common-mistakes-that-throw-errors-while-uploading-the-csv-file-and-solutions-to-avoid-them" tabindex="-1">Common mistakes that throw errors while uploading the CSV file and Solutions to avoid them <a class="header-anchor" href="#common-mistakes-that-throw-errors-while-uploading-the-csv-file-and-solutions-to-avoid-them" aria-label="Permalink to &quot;Common mistakes that throw errors while uploading the CSV file and Solutions to avoid them&quot;">​</a></h2><p>While uploading a CSV file, vendors generally do some common mistakes that need to be taken care of.</p><p>For this, the instruction file is provided in the app. The sellers need to follow certain instructions and avoid such errors in the CSV file upload.</p><h2 id="mistake-1-utf-8-not-encoded" tabindex="-1"><strong>Mistake 1:</strong> UTF-8 Not Encoded! <a class="header-anchor" href="#mistake-1-utf-8-not-encoded" aria-label="Permalink to &quot;**Mistake 1:** UTF-8 Not Encoded!&quot;">​</a></h2><p>You may get unwanted special characters as errors if your CSV file is not UTF-8 encoded. So, you need to confirm the UTF-8 encoding before you save any CSV file.</p><h3 id="solution" tabindex="-1"><strong>Solution</strong> <a class="header-anchor" href="#solution" aria-label="Permalink to &quot;**Solution**&quot;">​</a></h3><blockquote><p><strong>CSV file must include UTF 8 encoding</strong> to avoid the unwanted generation of special characters in the CSV file.</p></blockquote><h2 id="mistake-2-use-of-local-path-images" tabindex="-1"><strong>Mistake 2:</strong> Use of Local Path Images! <a class="header-anchor" href="#mistake-2-use-of-local-path-images" aria-label="Permalink to &quot;**Mistake 2:** Use of Local Path Images!&quot;">​</a></h2><p>The image field must contain the URLs of the product Images if the seller is using Method 2 to upload the products in bulk.</p><p>If the seller will use the local path images in the CSV file, it throws an error as shown in the below screenshot:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/zedqewfeferf.webp" alt="CSV file error"></p><p>CSV File Error</p><h3 id="solution-1" tabindex="-1"><strong>Solution</strong> <a class="header-anchor" href="#solution-1" aria-label="Permalink to &quot;**Solution**&quot;">​</a></h3><blockquote><p>You can use <strong>Amazon S3</strong> Or use <strong>Shopify CDN</strong>. <strong><a href="https://metafieldsmanager.thebestagency.com/tutorials/import/upload-assets" target="_blank" rel="noreferrer">Checkout the Detailed Guide</a></strong></p></blockquote><p><strong><a href="https://webkul.com/blog/merchant-amazon-s3-setup-multivendor-marketplace-for-shopify/" target="_blank" rel="noreferrer">Merchant Amazon S3 Setup Guide</a></strong></p><h2 id="mistake-3-no-default-title-value-in-case-of-no-variant" tabindex="-1"><strong>Mistake 3:</strong> No Default title value in case of No Variant! <a class="header-anchor" href="#mistake-3-no-default-title-value-in-case-of-no-variant" aria-label="Permalink to &quot;**Mistake 3:** No Default title value in case of No Variant!&quot;">​</a></h2><p>This is also a common mistake done by the sellers while uploading the Product CSV file.</p><p>So, in case the product has no variant, make sure that you are using a default title value in the product CSV file.</p><h3 id="solution-2" tabindex="-1"><strong>Solution</strong> <a class="header-anchor" href="#solution-2" aria-label="Permalink to &quot;**Solution**&quot;">​</a></h3><blockquote><p>For products with no variants, the option value should be set to &quot;Default Title&quot;.</p></blockquote><p>Make sure that sellers have added the option value as &quot;Default Title&quot; if any product has no variant.</p><h2 id="mistake-4-mismatch-of-columns-in-csv-file" tabindex="-1">Mistake 4: Mismatch of Columns in CSV file <a class="header-anchor" href="#mistake-4-mismatch-of-columns-in-csv-file" aria-label="Permalink to &quot;Mistake 4: Mismatch of Columns in CSV file&quot;">​</a></h2><p>Sometimes, admin upload the exact product CSV file downloaded from the Shopify store. This contradicts the instructions provided in the app and resulting in the column mismatch.</p><p>Mismatch of the number of attributes with the number of columns will throw errors while validating the CSV file.</p><p><strong>Solution</strong></p><p>The number of attributes must match with the number of columns in the CSV file.</p><blockquote><p><strong>The most suitable option is to:-<br> download</strong> the sample CSV file from the app.<br><strong>edit</strong> the file as per the requirement.<br><strong>validate</strong> the updated CSV file.<br><strong>upload</strong> the same in the app.</p></blockquote><h2 id="mistake-5-unrecognizable-character" tabindex="-1">Mistake 5: Unrecognizable Character <a class="header-anchor" href="#mistake-5-unrecognizable-character" aria-label="Permalink to &quot;Mistake 5: Unrecognizable Character&quot;">​</a></h2><p>Sometimes, sellers get an error as &quot;Validation Failed&quot; while uploading product CSV file. This may happen due to unrecognizable characters used in the CSV file.</p><blockquote><p><strong>Solution</strong>: Make sure that the characters used in the CSV file must contain a defined value.</p></blockquote><h2 id="mistake-6-additional-columns" tabindex="-1">Mistake 6: Additional Columns <a class="header-anchor" href="#mistake-6-additional-columns" aria-label="Permalink to &quot;Mistake 6: Additional Columns&quot;">​</a></h2><p>Adding additional columns in the product CSV results in the column mismatch issue.</p><p>This is the reason we suggest you download the sample CSV &amp; make the changes in the existing file as per your requirements to avoid column mismatch issues.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/csvfileuploadinssample.webp" alt="Seller Panel-Product Upload"></p><p>Seller Panel-Upload Product in Bulk</p><h3 id="solution-3" tabindex="-1">Solution <a class="header-anchor" href="#solution-3" aria-label="Permalink to &quot;Solution&quot;">​</a></h3><p>Make sure that the required fields in the CSV file cannot be empty.</p><h2 id="mistake-7-restricted-product-type-tag-collection" tabindex="-1">Mistake 7: Restricted Product Type, Tag &amp; Collection! <a class="header-anchor" href="#mistake-7-restricted-product-type-tag-collection" aria-label="Permalink to &quot;Mistake 7: Restricted Product Type, Tag &amp; Collection!&quot;">​</a></h2><p>In some cases, you may find a CSV error showing a message something like &quot;<strong>Product Type is restricted</strong>&quot;.</p><p>This error arises if the admin restricts the product type in the app &amp; the sellers are adding types other than those restricted types in the product CSV file.</p><p>Sometimes, the merchant wants to add a specific tag to their brand.</p><p>In this case, they can restrict product tags in the app so that sellers will be able to add only those restricted tags to the products.</p><p>Also, the merchant can restrict product type &amp; collection in the app.</p><p><strong>Restrict Product Tags</strong>, <strong>Product Types</strong> &amp; <strong>Collections</strong>:<br> Enabling these options will restrict product tags, types &amp; collections for the admin/sellers while adding/editing products.</p><p>Thus, the sellers will be adding only those tags, types &amp; collections to products that you have added in the app. And the same needs to be added in the product CSV file too.</p><h3 id="solution-4" tabindex="-1">Solution <a class="header-anchor" href="#solution-4" aria-label="Permalink to &quot;Solution&quot;">​</a></h3><p><strong>Mark:-</strong> Make sure that you have added the restricted <strong>Product Tags</strong>, <strong>Product Types</strong> &amp; <strong>Collections</strong> in the product CSV file.</p><blockquote><p>In simple words:-<br> If you have <strong>restricted the product tags</strong>, <strong>product types</strong> &amp; <strong>collections</strong> in the app, make sure that only those restricted options are added in the CSV file.</p></blockquote><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/sdferdgfreg.webp" alt="Restriction Configuration"></p><h2 id="restrict-collection-based-on-product-type" tabindex="-1">Restrict Collection Based On Product Type <a class="header-anchor" href="#restrict-collection-based-on-product-type" aria-label="Permalink to &quot;Restrict Collection Based On Product Type&quot;">​</a></h2><p>Now, the Admins can restrict collections based on the Product Type when products are added via CSV.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/ecfefercerccre.webp" alt="image"></p><p>If the above configuration is enabled, and a specific collection is assigned to a product type.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/01/csvproducttype.webp" alt="image"></p><p>Then, while filling in the CSV, the seller or admin must select the correct collection for the respective product type.</p><p>If the correct collection is not selected, an error will be shown during CSV validation.</p><p>Note: The Admin will need to enable the Restrict collection in order to add collection in the multivendor app.</p><h3 id="add-product-description-in-one-line" tabindex="-1">Add Product Description in One Line <a class="header-anchor" href="#add-product-description-in-one-line" aria-label="Permalink to &quot;Add Product Description in One Line&quot;">​</a></h3><p>NOTE:- The Product description of an item <strong>should not</strong> be added in multiple lines. To use more than one line, You need to use HTML tags.</p><p>**For Example:-</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">**&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;  </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Here is the Product Description:  </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;  </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;  </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Partywear, Washable, Do not Iron  </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">No replacement for this product, 1-month warranty.  </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><h3 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h3><p>To successfully validate and upload the CSV file in the Multi-vendor Marketplace app, please ensure you follow the required guidelines.</p><p><strong>POINTS TO BE NOTED:-</strong></p><p>-Firstly, always try to <strong>download the Product CSV file</strong> from the app, <strong>modify it as per your requirement</strong> and then, <strong>validate</strong> &amp; <strong>upload</strong> the same in the app.</p><p><strong>Suggestion</strong>:- Avoid uploading the exact CSV file downloaded from your Shopify store.</p><p>-The <strong>image URLs</strong> used in the CSV file should be <strong>publically accessible</strong>.</p><p>-Check the columns &amp; fields in the CSV files in case you have <strong>restricted product tags</strong>, <strong>product types</strong> &amp; <strong>collections</strong> in the app.</p><p>-Modify your CSV file once you add any <strong>custom fields</strong> in the app.</p><blockquote><p><strong>In Short</strong><br><strong>Keep updating Your Product CSV file in the app even if you make a small change in the Product Configuration.</strong></p></blockquote><blockquote><p><a href="https://webkul.com/blog/use-of-csv-files-for-bulk-upload/" target="_blank" rel="noreferrer"><strong>Learn</strong></a> to make the use of CSV files for Bulk Upload</p></blockquote>`,91)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
